    $('#edit-deposit-form',modal).onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,dt=new Date(collectedValue()),doc=f.elements.document.value.replace(/\D/g,'');if(!f.elements.donor.value.trim()||!validCedula(doc)||Number.isNaN(+dt)||dt>new Date()){toast('Revisa el nombre, una cédula válida y la fecha/hora de extracción.');return}try{if(serverMode)await api('deposits',{operation:'update',id:dep.id,type:dep.type,quantity:Math.max(1,+dep.quantity),donor:f.elements.donor.value.trim(),document:doc,collected:dt.toISOString()});else{dep.donor=f.elements.donor.value.trim();dep.document=doc;dep.collected=dt.toISOString();const life=({whole_blood:42,red_cells:42,platelets:5,plasma:365,sangre_entera:42,globulos_rojos:42,plaquetas:5})[dep.component]||42;dep.expiry=new Date(+dt+life*864e5).toISOString();persist()}close();await reloadRemote();toast('Lote actualizado.')}catch(err){toast(err.message)}};
